    // MARK: Convenience accessors

    /// Legacy accessor — placement_id → (x, y).
    /// Kept for call sites that only need the fractional position.
    static let positions: [Int: SIMD2<Float>] = {
        var m: [Int: SIMD2<Float>] = [:]
        m.reserveCapacity(sockets.count)
        for (id, s) in sockets {
            m[id] = SIMD2<Float>(s.x, s.y)
        }
        return m
    }()

    /// Placement IDs of all 323 bolt-on handholds.
    static let boltOnIds: Set<Int> = Set(
        sockets.values.filter { $0.setId == boltOnSetId }.map(\.placementId)
    )

    /// Placement IDs of all 153 screw-on foot chips.
    static let screwOnIds: Set<Int> = Set(
        sockets.values.filter { $0.setId == screwOnSetId }.map(\.placementId)
    )
